import assert from 'node:assert/strict';
import {stripTypeScriptTypes} from 'node:module';
import {readFileSync} from 'node:fs';
const source=readFileSync(new URL('../web/src/features/Composer.schedule-model.ts',import.meta.url),'utf8');
const model=await import('data:text/javascript,'+encodeURIComponent(stripTypeScriptTypes(source)));
const {captureSchedule,submitSchedule,localScheduleTime,scheduleDue,scheduleReason,scheduleEdit,unchangedScheduledFiles}=model;
const file=new File(['real bytes'],'same.txt'),draft={text:'[@Casey](agentnet:person/abc) exact',topic:'topic',replyTo:'reply',files:[{key:'one',file,name:file.name,size:file.size,type:''}]};
const audience={persons:['person'],pids:['pid'],author_pid:'author'};
const due=Date.now()+3600000,id='a'.repeat(32);
const attempt=captureSchedule(id,'conv',draft.text,draft,new Date(due).toISOString(),'UTC',audience);
audience.persons.push('widened');draft.text='new typing';
assert.deepEqual(attempt.payload.audience.persons,['person']);assert.notEqual(attempt.draft.text,draft.text);
let stage=0,created=0,rows=new Map(),posts=[];
const api={stage:async f=>{assert.equal(f,file);return 'stage'+(++stage)},discard:async()=>{},createSchedule:async payload=>{
 posts.push(structuredClone(payload));assert.equal(payload.files[0],'stage'+stage);
 const canonical=JSON.stringify({...payload,files:['verified exact bytes']});
 if(rows.has(payload.id)&&rows.get(payload.id)!==canonical)throw Object.assign(Error('conflict'),{code:'scheduled_id_conflict'});
 rows.set(payload.id,canonical);if(!created++)throw Error('response lost');return {id:payload.id,state:'pending'};
}};
await assert.rejects(submitSchedule(api,attempt),/response lost/);assert.equal(rows.size,1);
await submitSchedule(api,attempt);assert.equal(rows.size,1);assert.equal(stage,2);assert.equal(posts[0].id,posts[1].id);
assert.deepEqual({...posts[0],files:undefined},{...posts[1],files:undefined});
const changed=captureSchedule(id,'conv','different',attempt.draft,attempt.payload.due,'UTC',attempt.payload.audience);
await assert.rejects(submitSchedule(api,changed),/conflict/);assert.equal(rows.size,1);
assert.throws(()=>captureSchedule(id,'conv','text',draft,new Date(0).toISOString(),'UTC',audience),/future/);
assert.equal(scheduleDue(localScheduleTime(new Date(due))).slice(0,16),new Date(due).toISOString().slice(0,16));
const current={...attempt.draft,text:'new typing',files:[...attempt.files,{key:'two',file:new File(['new'],'new.txt')}]};
assert.equal(unchangedScheduledFiles(current,attempt).length,1);assert.equal(current.text,'new typing');assert.equal(current.files.length,2);
assert.equal(unchangedScheduledFiles({...current,newTopic:true},attempt),null);
assert.equal(unchangedScheduledFiles({...current,topic:'other'},attempt),null);
assert.equal(unchangedScheduledFiles({...current,files:[{...attempt.files[0],file:new File(['changed'],'same.txt')}]},attempt).length,0);
const row={id,rev:4,conv:'conv',topic:'topic',body:'old',due:attempt.payload.due,timezone:'UTC',audience:attempt.payload.audience,files:[{name:'same.txt',size:10,sha256:'x'}]};
const edit=scheduleEdit(row,'edited',attempt.payload.due,'UTC',false);
assert.equal(edit.rev,4);assert(!('audience'in edit));assert(!('files'in edit));
assert.deepEqual(scheduleEdit(row,'edited',attempt.payload.due,'UTC',true,audience).files,[]);
assert.equal(scheduleEdit(row,'edited',attempt.payload.due,'UTC',false,audience).audience,audience);
const eligible={supported:true,conv:'conv',ordinary:true};assert.equal(scheduleReason(eligible),'');
for(const flag of ['frozen','visitor','newTopic','missing','followup'])assert(scheduleReason({...eligible,[flag]:true}),flag);
assert(scheduleReason({...eligible,ordinary:false}));assert(scheduleReason({...eligible,supported:false}));
console.log('PASS real scheduling model: immutable payload/files/audience; lost response same-ID re-stage one row; conflict/past guards; changed draft/file/topic; edits retain audience/files; eligibility/timezone');
const opaque={workspace:'bound-host',name:file.name,size:file.size,arrayBuffer:()=>file.arrayBuffer()};
await submitSchedule({stage:async()=>opaque,discard:async()=>{},createSchedule:async p=>{assert.equal(p.files[0],opaque,'browser opaque wrapper remains unmodified');assert.equal(new TextDecoder().decode(await p.files[0].arrayBuffer()),'real bytes');return{id:p.id};}},attempt);
assert.throws(()=>scheduleEdit({...row,files:[]},'',attempt.payload.due,'UTC',false),/message|attachment/);
console.log('PASS browser same-host opaque File handle preserves actual bytes, and empty edit is refused');
